      "translation": "Nearby, each one plays a biwa. This is the Yuruori Rigoto, the Tsukibiwa. Set it to the east, spread out bracken rags, and lay out a rope to use as a bed for the night. Open a window in the east wall and let out the water. There is a gap in the pillow. I'm going to fold this up. A small plot of land was set aside to the north of the hermitage, and the thorny Himegaki fence was used as a garden. Sunaha was eating all kinds of strawberry grass. This is how Karinoan is. As it wandered around that place, it ran to the south and gathered water by bending down on rocks. If it's near Hayashiken, I won't hesitate to pick up a tree. His name is Toyama. Follow Masaki's Kazurato. The valley is dark, but the weather is sunny. There is no need for inspiration. In spring, you can see the wisteria and smell it in the west like purple clouds. Summer listens to the Duke of Guo and tears up the mountain path of death. Autumn is filled with the sounds of the sun. I wonder if I will enjoy the world of Utsusemi. In winter, we admire snow. Dear Lord, please forgive me for my sins. If I am not happy, and I am not happy, I will take rest, and there will be no one to wander about, and no friends to worship. Even if you don't want to say anything, if you're alone, you should wake up to Kugofu. Although we must always abide by the commandments, if there are no boundaries, we will break them no matter what. Tomorrow, when I take refuge in the white waves, I will look at the boats passing by in Oka-no-ya, and the Mansaya will pass away, and if the wind of Katsura leaves the leaves rustling, I will think of the river of Penyang and follow the flow of the Minamoto Governor. If I have too much fun, I often listen to the autumn breeze in the light of the pine trees, and make music to the sounds of the water and the flowing springs. Although this is art, it is not something that pleases the human ear."
